here = os.path.dirname(os.path.abspath(__file__))
tofauti, hazipo = [], []
for rel, want in sorted(MANIFEST.items()):
    path = os.path.join(here, *rel.split("/"))
    if not os.path.exists(path):
        hazipo.append(rel)
        continue
    got = hashlib.sha256(open(path, "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != want:
        tofauti.append(rel)
print(f"Faili {len(MANIFEST)} zimekaguliwa kwenye: {here}")
print(f"Ni za zamani/tofauti: {len(tofauti)}")
for r in tofauti: print("   *", r)
print(f"Hazipo: {len(hazipo)}")
for r in hazipo: print("   -", r)
if not tofauti and not hazipo:
    print("Kila kitu ni toleo la sasa.")
sys.exit(1 if tofauti or hazipo else 0)
